// Demo: MSG_ZEROCOPY Sockets — copy cost at 10 Gbps
var gbps=10,bytesPerSec=gbps*1e9/8;
var copyCost=bytesPerSec*20/3e9;
console.log('technique: MSG_ZEROCOPY Sockets');console.log('throughput: '+gbps+' Gbps = '+(bytesPerSec/1e6).toFixed(0)+' MB/s');
console.log('one copy costs: '+copyCost.toFixed(1)+' CPU cores');
console.log('zero-copy saves those cores for application work');

// Demo: DMA-BUF Sharing — buffer pool recycling
var pool=64,used=0,peak=0;
for(var i=0;i<24*10;i++){if(((i*13+4)%2)===0&&used<pool){used++;}else if(used>0){used--;}
peak=Math.max(peak,used);}
console.log('technique: DMA-BUF Sharing');console.log('pool: '+pool+', peak in use: '+peak);
console.log(peak<pool?'no allocation in the fast path — buffers recycled':'pool exhausted — grow it');

